function bindCheck(cb, sel){
  const c = $$(cb), s = $$(sel);
  if (!c || !s) return;
  c.checked = checkOn();
  s.value = String(thresh());
  c.onchange = () => { LS.set("kombi-op-check", c.checked ? "1" : "0"); syncCheck(); };
  s.onchange = () => { LS.set("kombi-op-thresh", s.value); syncCheck(); if (op.rep) renderRep(); };
}
function syncCheck(){
  [["opChkOn1","opChkLvl1"], ["opChkOn2","opChkLvl2"]].forEach(([cb, sel]) => {
    const c = $$(cb), s = $$(sel);
    if (c) c.checked = checkOn();
    if (s) s.value = String(thresh());
  });
}
