$$("opIOCopy").onclick = () => {
  $$("opIOText").select();
  try { navigator.clipboard.writeText($$("opIOText").value); } catch(e){ try { document.execCommand("copy"); } catch(e2){} }
  $$("opIOCopy").textContent = "Скопировано";
  setTimeout(() => $$("opIOCopy").textContent = "Скопировать", 1500);
};
